{
  "story": "Follow the journey of a journal entry as it gets posted into the general ledger and updates the cash account balance.",
  "aha": {
    "stateId": "post",
    "observation": "Posting moves the verified debit or credit directly into the cash ledger, immediately shifting the running balance."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "values": "state.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": [
        "Draft",
        "Verify",
        "Post",
        "Balance"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Standard Variant",
        "regions": [
          {
            "id": "journal",
            "label": "Journal Entry",
            "kind": "log",
            "values": ["Debit Cash 500", "Credit AR 500"]
          },
          {
            "id": "ledger",
            "label": "Cash Ledger",
            "kind": "account",
            "values": ["1200", "1700"]
          }
        ],
        "states": [
          {
            "id": "draft",
            "label": "Draft",
            "sentence": "Create the initial journal entry.",
            "why": "Transaction is recorded first in the journal before touching any ledger.",
            "active": ["journal"],
            "calloutRegion": "journal",
            "readouts": [
              {
                "id": "r1",
                "label": "Entry Status",
                "value": "Unposted"
              }
            ]
          },
          {
            "id": "verify",
            "label": "Verify",
            "sentence": "Confirm debits equal credits.",
            "why": "Double-check the math and accounts before final posting.",
            "active": ["journal"],
            "calloutRegion": "journal",
            "readouts": [
              {
                "id": "r2",
                "label": "Balance Check",
                "value": "Balanced"
              }
            ]
          },
          {
            "id": "post",
            "label": "Post",
            "sentence": "Transfer the entry to the cash ledger.",
            "why": "Posting moves data from the journal to the specific ledger account.",
            "active": ["ledger"],
            "calloutRegion": "ledger",
            "readouts": [
              {
                "id": "r3",
                "label": "Posted Amount",
                "value": "+500 USD"
              }
            ]
          },
          {
            "id": "balance",
            "label": "Balance",
            "sentence": "Calculate the final cash total.",
            "why": "The new ledger total reflects all posted entries.",
            "active": ["ledger"],
            "calloutRegion": "ledger",
            "readouts": [
              {
                "id": "r4",
                "label": "Ending Cash",
                "value": "1700 USD"
              }
            ]
          }
        ]
      }
    ]
  }
}
